function memoize(fn) {
  const cache = new Map();
  return function (n) {
    if (cache.has(n)) return 'cached:' + cache.get(n);
    const val = fn(n);
    cache.set(n, val);
    return 'fresh:' + val;
  };
}
let work = 0;
const square = memoize((n) => {
  work += 1;
  return n * n;
});
console.log(square(4), square(4), square(5), work);

